    // Download Stats Logic
    async function updateDownloadStats() {
        try {
            const response = await fetch('download_stats.json?t=' + new Date().getTime());
            if (!response.ok) return;
            const data = await response.json();

            document.getElementById('dl-model-name').textContent = data.current_model || "Waiting...";
            document.getElementById('dl-text').textContent = data.percentage + '%';
            document.getElementById('dl-bar').style.width = data.percentage + '%';
            document.getElementById('dl-eta').textContent = 'ETA: ' + (data.eta || '--:--:--');
            document.getElementById('dl-speed').textContent = data.speed || '-- MB/s';

            if (data.queue && Array.isArray(data.queue)) {
                let queueHtml = '<div style="margin-bottom: 5px;"><strong>Queue:</strong></div>';
                data.queue.forEach(item => {
                    let statusClass = item.status === 'downloading' ? 'active' : (item.status === 'done' ? 'done' : '');
                    queueHtml += `<div class="queue-item ${statusClass}">• ${item.name}</div>`;
                });
                document.getElementById('dl-queue').innerHTML = queueHtml;
            }
        } catch (error) {
            console.log("Waiting for download backend...", error);
        }
    }
    setInterval(updateDownloadStats, 2000);
    updateDownloadStats();
</script>

